CREATE OR REPLACE FUNCTION inventario_private.actualizar_tarea(p_ticket uuid, p_version integer, p_accion text, p_avance integer, p_nota text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.inventario_tickets; role_name text; next_state text;
begin
 select * into t from public.inventario_tickets where id=p_ticket for update;
 role_name:=inventario_private.rol_bodega(t.bodega_id);
 if t.id is null or role_name is null or not inventario_private.puede_leer_ticket(t.id) then raise exception 'Acceso denegado' using errcode='42501'; end if;
 if role_name='administrador' then raise exception 'Administración solo tiene acceso de consulta y seguimiento' using errcode='42501'; end if;
 if t.modo<>'categoria' then raise exception 'Conteo SKU pendiente de integración'; end if;
 if p_version is null or t.version<>p_version then raise exception 'La tarea cambió. Actualiza antes de continuar' using errcode='40001'; end if;
 if p_accion is null or length(coalesce(p_nota,''))>2000 then raise exception 'Datos inválidos'; end if;
 if t.total_productos>0 and p_accion='avance' then raise exception 'El avance se calcula con los productos contados'; end if;
 if t.total_productos>0 and p_accion='finalizar' and t.productos_contados<>t.total_productos then raise exception 'Debes contar todos los productos antes de finalizar'; end if;
 next_state:=t.estado;
 if p_accion in ('iniciar','avance','finalizar') then
  if t.asignado_a is distinct from auth.uid() or role_name<>'operador' then raise exception 'Solo el operador asignado puede registrar el trabajo' using errcode='42501'; end if;
  if p_accion='iniciar' and t.estado='asignado' then next_state:='en_proceso';
  elsif p_accion='avance' and t.estado='en_proceso' and p_avance between 26 and 69 and p_avance>=t.avance_parcial and length(btrim(coalesce(p_nota,'')))>0 then
   update public.inventario_tickets set avance_parcial=p_avance where id=t.id;
  elsif p_accion='finalizar' and t.estado='en_proceso' then next_state:='enviado_verificacion';
  else raise exception 'Transición o avance no válido'; end if;
 else
  if role_name<>'lider' or t.asignado_a=auth.uid() then raise exception 'Se requiere un supervisor distinto del operador' using errcode='42501'; end if;
  if p_accion='revisar' and t.estado='enviado_verificacion' then next_state:='en_verificacion';
  elsif p_accion='verificar' and t.estado='en_verificacion' and length(btrim(coalesce(p_nota,'')))>0 then next_state:='verificado_sin_diferencias';
  elsif p_accion='diferencias' and t.estado='en_verificacion' and length(btrim(coalesce(p_nota,'')))>0 then next_state:='verificado_con_diferencias';
  elsif p_accion='cerrar' and t.estado='verificado_sin_diferencias' then next_state:='cerrado';
  elsif p_accion='cerrar_diferencias' and t.estado='verificado_con_diferencias' and length(btrim(coalesce(p_nota,'')))>0 then next_state:='cerrado';
  elsif p_accion='devolver' and t.estado in ('en_verificacion','verificado_con_diferencias') and length(btrim(coalesce(p_nota,'')))>0 then
   next_state:='en_proceso';
   update public.inventario_tarea_productos set cantidad_contada=null,contado_por=null,contado_at=null where ticket_id=t.id;
   update public.inventario_tickets set productos_contados=0 where id=t.id;
   update public.inventario_tickets set avance_parcial=25,enviado_at=null,verificacion_iniciada_at=null,verificacion_finalizada_at=null where id=t.id;
  else raise exception 'Transición no válida o falta observación'; end if;
 end if;
 update public.inventario_tickets set estado=next_state,version=version+1,
 aceptado_at=case when p_accion='iniciar' then now() else aceptado_at end,
 iniciado_at=case when p_accion='iniciar' then now() else iniciado_at end,
 enviado_at=case when p_accion='finalizar' then now() else enviado_at end,
 verificacion_iniciada_at=case when p_accion='revisar' then now() else verificacion_iniciada_at end,
 recibido_at=case when p_accion='revisar' then now() else recibido_at end,
 verificacion_finalizada_at=case when p_accion in ('verificar','diferencias') then now() else verificacion_finalizada_at end,
 cierre_con_diferencias=case when p_accion='cerrar_diferencias' then true else cierre_con_diferencias end,
 justificacion_cierre=case when p_accion='cerrar_diferencias' then btrim(p_nota) else justificacion_cierre end,
 cerrado_at=case when p_accion in ('cerrar','cerrar_diferencias') then now() else cerrado_at end where id=t.id;
 insert into public.inventario_auditoria(bodega_id,ticket_id,actor_id,actor_original_id,actor_rol,evento,entidad_tipo,entidad_id,estado_anterior,estado_nuevo,motivo,operacion_clave)
 values(t.bodega_id,t.id,auth.uid(),auth.uid(),role_name,p_accion,'ticket',t.id,t.estado,next_state,
 case when p_accion='avance' then p_avance::text||'% — '||p_nota else p_nota end,gen_random_uuid());
end $function$

CREATE OR REPLACE FUNCTION inventario_private.contar_producto(p_item uuid, p_version integer, p_cantidad text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item public.inventario_tarea_productos; t public.inventario_tickets; qty numeric(20,6);
begin
 select * into item from public.inventario_tarea_productos where id=p_item;
 select * into t from public.inventario_tickets where id=item.ticket_id for update;
 if t.id is null or t.asignado_a is distinct from auth.uid() or coalesce(inventario_private.rol_bodega(t.bodega_id),'')<>'operador'
 then raise exception 'Solo el operador asignado puede contar' using errcode='42501'; end if;
 if p_version is null or t.version<>p_version then raise exception 'La tarea cambió. Actualiza antes de continuar' using errcode='40001'; end if;
 if t.estado<>'en_proceso' then raise exception 'La tarea debe estar en proceso'; end if;
 if p_cantidad is null or p_cantidad!~'^[0-9]{1,14}(\.[0-9]{1,6})?$' then raise exception 'Cantidad inválida; utiliza números positivos o cero, con hasta seis decimales'; end if;
 qty:=p_cantidad::numeric(20,6);
 update public.inventario_tarea_productos set cantidad_contada=qty,contado_por=auth.uid(),contado_at=now() where id=p_item;
 update public.inventario_tickets set productos_contados=(select count(*) from public.inventario_tarea_productos where ticket_id=t.id and cantidad_contada is not null),version=version+1 where id=t.id;
 insert into public.inventario_auditoria(bodega_id,ticket_id,actor_id,actor_original_id,actor_rol,evento,entidad_tipo,entidad_id,motivo,operacion_clave)
 values(t.bodega_id,t.id,auth.uid(),auth.uid(),'operador','producto_contado','producto_tarea',p_item,
 item.codigo||': '||coalesce(item.cantidad_contada::text,'sin contar')||' → '||qty::text,gen_random_uuid());
end $function$

CREATE OR REPLACE FUNCTION inventario_private.observacion_guardar(p_ticket uuid, p_texto text, p_version integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.inventario_tickets; o public.inventario_observaciones_conteo;
begin
 select * into t from public.inventario_tickets where id=p_ticket for update;
 if t.asignado_a is distinct from auth.uid() or coalesce(inventario_private.rol_bodega(t.bodega_id),'')<>'operador' then raise exception 'No puedes editar esta observación' using errcode='42501'; end if;
 if t.estado<>'en_proceso' or p_texto is null or length(p_texto)>2000 then raise exception 'Revisa el estado y la observación'; end if;
 select * into o from public.inventario_observaciones_conteo where ticket_id=p_ticket;
 if p_version is distinct from coalesce(o.version,0) then raise exception 'La observación cambió. Recarga antes de guardar' using errcode='40001'; end if;
 insert into public.inventario_observaciones_conteo(ticket_id,usuario_id,texto) values(p_ticket,auth.uid(),p_texto)
 on conflict(ticket_id) do update set texto=excluded.texto,usuario_id=excluded.usuario_id,version=inventario_observaciones_conteo.version+1,updated_at=now();
 insert into public.inventario_auditoria(bodega_id,ticket_id,actor_id,actor_original_id,actor_rol,evento,entidad_tipo,entidad_id,motivo,operacion_clave)
 values(t.bodega_id,t.id,auth.uid(),auth.uid(),'operador','observacion_guardada','ticket',t.id,coalesce(o.texto,'')||' → '||p_texto,gen_random_uuid());
end $function$

CREATE OR REPLACE FUNCTION inventario_private.revisar_conteo(p_ticket uuid, p_version integer, p_accion text, p_nota text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.inventario_tickets; diferencias boolean; destino text;
begin
 select * into t from public.inventario_tickets where id=p_ticket for update;
 if t.id is null or coalesce(inventario_private.rol_bodega(t.bodega_id),'')<>'lider'
 or not inventario_private.puede_leer_ticket(t.id) or t.asignado_a=auth.uid() then
  raise exception 'Solo un líder distinto del operador puede revisar este inventario' using errcode='42501';
 end if;
 if p_version is null or p_version<>t.version then raise exception 'La tarea cambió. Actualiza antes de continuar' using errcode='40001'; end if;
 if t.modo<>'categoria' or t.estado not in ('enviado_verificacion','en_verificacion','verificado_sin_diferencias','verificado_con_diferencias') then raise exception 'Este inventario no está pendiente de revisión'; end if;
 if p_accion is null or p_accion not in ('verificar_cerrar','devolver') or length(btrim(coalesce(p_nota,'')))=0 or length(p_nota)>2000 then raise exception 'Indica una observación de revisión de hasta 2000 caracteres'; end if;
 if p_accion='verificar_cerrar' then
  if not exists(select 1 from public.inventario_tarea_productos where ticket_id=t.id)
  or exists(select 1 from public.inventario_tarea_productos p left join inventario_private.referencias_producto r on r.producto_id=p.id
   where p.ticket_id=t.id and (p.cantidad_contada is null or r.producto_id is null)) then
   raise exception 'Faltan conteos o cantidades de referencia. No se puede determinar el resultado todavía';
  end if;
  select exists(select 1 from public.inventario_tarea_productos p join inventario_private.referencias_producto r on r.producto_id=p.id
   where p.ticket_id=t.id and p.cantidad_contada<>r.cantidad) into diferencias;
  -- Preserve existing result and evidence triggers. Intermediate state is never committed separately.
  update public.inventario_tickets set estado=case when diferencias then 'verificado_con_diferencias' else 'verificado_sin_diferencias' end where id=t.id;
  destino:='cerrado';
  update public.inventario_tickets set estado=destino,version=version+1,lider_id=auth.uid(),
   recibido_at=coalesce(recibido_at,now()),verificacion_iniciada_at=coalesce(verificacion_iniciada_at,now()),
   verificacion_finalizada_at=now(),cerrado_at=now(),cierre_con_diferencias=diferencias,justificacion_cierre=case when diferencias then btrim(p_nota) else null end where id=t.id;
 else
  destino:='en_proceso';
  update public.inventario_tarea_productos set cantidad_contada=null,contado_por=null,contado_at=null where ticket_id=t.id;
  update public.inventario_tickets set estado=destino,version=version+1,lider_id=auth.uid(),productos_contados=0,avance_parcial=25,
   enviado_at=null,verificacion_iniciada_at=null,verificacion_finalizada_at=null,cerrado_at=null,
   cierre_con_diferencias=false,justificacion_cierre=null where id=t.id;
 end if;
 insert into public.inventario_auditoria(bodega_id,ticket_id,actor_id,actor_original_id,actor_rol,evento,entidad_tipo,entidad_id,estado_anterior,estado_nuevo,motivo,operacion_clave)
 values(t.bodega_id,t.id,auth.uid(),auth.uid(),'lider',
  case when p_accion='devolver' then 'devolver' when diferencias then 'verificado_cerrado_con_diferencias' else 'verificado_cerrado_sin_diferencias' end,
  'ticket',t.id,t.estado,destino,btrim(p_nota),gen_random_uuid());
end $function$
